window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6db55e35107c98cf"]={"versions": [{"id": "FIG-6db55e35107c98cf", "releases": ["R4.0.3", "R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Struktur- und Metamodell-Übersichtsdiagramm (informelle Composite-Structure-Notation).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Template-Spezifikation für Hardware-Ressourcen (<code>AUTOSAR_TPS_ECUResourceTemplate</code>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Abstraktions- und Granularitätskonzepts zur Modellierung von Hardware-Topologien innerhalb eines Steuergeräts (ECU). Es bildet die Brücke zwischen grobgranularer Systemarchitektur (Hardware-Kompositionen wie Prozessor, Memory, Peripherie, Transceiver) und feingranularem Pin-/Pad-Level für die MCAL-Treiberkonfiguration und Signalzuweisung im AUTOSAR-Entwicklungsprozess.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Hardware Element</code> (<code>HwElement</code>):</strong>\n<ul class=\"fig-list\"><li>Basiskomponente des Metamodells zur Repräsentation physischer Einheiten (z. B. gesamte ECU, Mikrocontroller, Processing Unit/Core, Peripheriemodul, Flash/RAM, Transceiver, Sensoren/Aktoren).\n</li><li><strong>Hierarchische Schachtelung:</strong> Rekursive Aggregation (<code>HwElement</code> enthält Sub-<code>HwElement</code>e). Ermöglicht hierarchische Sichten (ECU → Microcontroller → Peripherie-IPs).\n</li></ul>\n</li><li><strong><code>Hardware Pin Group</code> (<code>HwPinGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Logische oder funktionale Bündelung mehrerer Pins eines Hardware-Elements (z. B. SPI-Interface mit MOSI/MISO/CLK/CS, CAN-Tx/Rx, Port-Bank).\n</li><li>Dient als Zwischenabstraktion, um Verbindungen modular und übersichtlich ohne voll aufgelöste Einzeldraht-Modellierung zu definieren.\n</li></ul>\n</li><li><strong><code>Hardware Pin</code> (<code>HwPin</code>):</strong>\n<ul class=\"fig-list\"><li>Kleinste diskrete Modellierungseinheit; repräsentiert ein physisches/elektrisches Pad, Ball (BGA) oder Lead (Gehäuseanschluss) eines Halbleiters bzw. Steckverbinders.\n</li></ul>\n</li><li><strong><code>Hardware Connection</code> (<code>HwConnection</code>):</strong>\n<ul class=\"fig-list\"><li>Assoziations- bzw. Verbindungsklasse zur Modellierung physikalischer/elektrischer Signalpfade (Leiterbahnen, Kabelbäume, Busse).\n</li><li><strong>Mehrstufige Modellierungsgranularität (Multi-Level Abstraction):</strong>\n<ol class=\"fig-list\"><li><em>Element-to-Element:</em> Verbindung direkt zwischen zwei <code>HwElement</code>-Instanzen (abstrakter Strukturüberblick ohne Pin-Detail).\n</li><li><em>Group-to-Group / Group-to-Pin:</em> Verbindung zwischen <code>HwPinGroup</code> und Ziel-Pins (z. B. Interface-Level).\n</li><li><em>Pin-to-Pin:</em> Diskrete Verdrahtung zur exakten Festlegung von Signalführung und elektrischen Parametern.\n</li></ol>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht anwendbar (statisches Deklarationsmodell):</strong> Das Diagramm definiert rein statische Metadaten-Strukturen für ARXML-Beschreibungsdateien. Es existiert kein Laufzeitverhalten, keine State Machine und keine dynamische Interaktion (keine RTE-, Det- oder Dem-Beteiligung zur Laufzeit).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Generierung &amp; Tool-Kette:</strong>\n<ul class=\"fig-list\"><li>Fundament für Halbleiterhersteller (Semiconductor Vendors) zur Bereitstellung standardisierter Hardware-Beschreibungen (HwDescription ARXML).\n</li><li>Ermöglicht AUTOSAR-Autorensystemen (System Authoring Tools) Plausibilitätsprüfungen, ob zugeordnete Software-Komponenten (SWCs) und BSW-Module physikalisch auf den verfügbaren Kernen und Peripherien abgebildet werden können.\n</li></ul>\n</li><li><strong>MCAL-Konfiguration &amp; Signal-Pin-Mapping:</strong>\n<ul class=\"fig-list\"><li><strong>Port / DIO Driver:</strong> Das <code>HwPin</code>- und <code>HwPinGroup</code>-Modell steuert direkt die Generierung der MCAL-Port-Konfiguration (<code>PortPin</code>, Multiplexing-Optionen, Direction, Pull-Up/Pull-Down).\n</li><li><strong>Kommunikationstreiber (CAN/LIN/SPI/ETH):</strong> Die Abbildung von <code>HwPinGroup</code> auf Peripherie-Pins legt die Zuweisung von Hardware-Controllern zu physikalischen Transceivern auf dem PCB fest.\n</li></ul>\n</li><li><strong>Integrations-Constraint:</strong>\n<ul class=\"fig-list\"><li>Fehlende oder unzureichend aufgelöste Pin-Level-Modelle (<code>HwPin Connection</code>) verhindern die automatisierte Parametrisierung der I/O-Hardware-Abstraktionsschicht (IoHwAb) und der BSW-Treiberstacks, da Generator-Skripte zwingend die exakte Pin-ID für Register-Bitmasken benötigen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-1b73dbcefe8c9461", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Struktur- und Metamodell-Übersichtsdiagramm (informelle Composite-Structure-Notation).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Template-Spezifikation für Hardware-Ressourcen (<code>AUTOSAR_TPS_ECUResourceTemplate</code>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Abstraktions- und Granularitätskonzepts zur Modellierung von Hardware-Topologien innerhalb eines Steuergeräts (ECU). Es bildet die Brücke zwischen grobgranularer Systemarchitektur (Hardware-Kompositionen wie Prozessor, Memory, Peripherie, Transceiver) und feingranularem Pin-/Pad-Level für die MCAL-Treiberkonfiguration und Signalzuweisung im AUTOSAR-Entwicklungsprozess.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Hardware Element</code> (<code>HwElement</code>):</strong>\n<ul class=\"fig-list\"><li>Basiskomponente des Metamodells zur Repräsentation physischer Einheiten (z. B. gesamte ECU, Mikrocontroller, Processing Unit/Core, Peripheriemodul, Flash/RAM, Transceiver, Sensoren/Aktoren).\n</li><li><strong>Hierarchische Schachtelung:</strong> Rekursive Aggregation (<code>HwElement</code> enthält Sub-<code>HwElement</code>e). Ermöglicht hierarchische Sichten (ECU → Microcontroller → Peripherie-IPs).\n</li></ul>\n</li><li><strong><code>Hardware Pin Group</code> (<code>HwPinGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Logische oder funktionale Bündelung mehrerer Pins eines Hardware-Elements (z. B. SPI-Interface mit MOSI/MISO/CLK/CS, CAN-Tx/Rx, Port-Bank).\n</li><li>Dient als Zwischenabstraktion, um Verbindungen modular und übersichtlich ohne voll aufgelöste Einzeldraht-Modellierung zu definieren.\n</li></ul>\n</li><li><strong><code>Hardware Pin</code> (<code>HwPin</code>):</strong>\n<ul class=\"fig-list\"><li>Kleinste diskrete Modellierungseinheit; repräsentiert ein physisches/elektrisches Pad, Ball (BGA) oder Lead (Gehäuseanschluss) eines Halbleiters bzw. Steckverbinders.\n</li></ul>\n</li><li><strong><code>Hardware Connection</code> (<code>HwConnection</code>):</strong>\n<ul class=\"fig-list\"><li>Assoziations- bzw. Verbindungsklasse zur Modellierung physikalischer/elektrischer Signalpfade (Leiterbahnen, Kabelbäume, Busse).\n</li><li><strong>Mehrstufige Modellierungsgranularität (Multi-Level Abstraction):</strong>\n<ol class=\"fig-list\"><li><em>Element-to-Element:</em> Verbindung direkt zwischen zwei <code>HwElement</code>-Instanzen (abstrakter Strukturüberblick ohne Pin-Detail).\n</li><li><em>Group-to-Group / Group-to-Pin:</em> Verbindung zwischen <code>HwPinGroup</code> und Ziel-Pins (z. B. Interface-Level).\n</li><li><em>Pin-to-Pin:</em> Diskrete Verdrahtung zur exakten Festlegung von Signalführung und elektrischen Parametern.\n</li></ol>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht anwendbar (statisches Deklarationsmodell):</strong> Das Diagramm definiert rein statische Metadaten-Strukturen für ARXML-Beschreibungsdateien. Es existiert kein Laufzeitverhalten, keine State Machine und keine dynamische Interaktion (keine RTE-, Det- oder Dem-Beteiligung zur Laufzeit).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Generierung &amp; Tool-Kette:</strong>\n<ul class=\"fig-list\"><li>Fundament für Halbleiterhersteller (Semiconductor Vendors) zur Bereitstellung standardisierter Hardware-Beschreibungen (HwDescription ARXML).\n</li><li>Ermöglicht AUTOSAR-Autorensystemen (System Authoring Tools) Plausibilitätsprüfungen, ob zugeordnete Software-Komponenten (SWCs) und BSW-Module physikalisch auf den verfügbaren Kernen und Peripherien abgebildet werden können.\n</li></ul>\n</li><li><strong>MCAL-Konfiguration &amp; Signal-Pin-Mapping:</strong>\n<ul class=\"fig-list\"><li><strong>Port / DIO Driver:</strong> Das <code>HwPin</code>- und <code>HwPinGroup</code>-Modell steuert direkt die Generierung der MCAL-Port-Konfiguration (<code>PortPin</code>, Multiplexing-Optionen, Direction, Pull-Up/Pull-Down).\n</li><li><strong>Kommunikationstreiber (CAN/LIN/SPI/ETH):</strong> Die Abbildung von <code>HwPinGroup</code> auf Peripherie-Pins legt die Zuweisung von Hardware-Controllern zu physikalischen Transceivern auf dem PCB fest.\n</li></ul>\n</li><li><strong>Integrations-Constraint:</strong>\n<ul class=\"fig-list\"><li>Fehlende oder unzureichend aufgelöste Pin-Level-Modelle (<code>HwPin Connection</code>) verhindern die automatisierte Parametrisierung der I/O-Hardware-Abstraktionsschicht (IoHwAb) und der BSW-Treiberstacks, da Generator-Skripte zwingend die exakte Pin-ID für Register-Bitmasken benötigen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-5415339cbf79f867", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Struktur- und Metamodell-Übersichtsdiagramm (informelle Composite-Structure-Notation).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Template-Spezifikation für Hardware-Ressourcen (<code>AUTOSAR_TPS_ECUResourceTemplate</code>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Abstraktions- und Granularitätskonzepts zur Modellierung von Hardware-Topologien innerhalb eines Steuergeräts (ECU). Es bildet die Brücke zwischen grobgranularer Systemarchitektur (Hardware-Kompositionen wie Prozessor, Memory, Peripherie, Transceiver) und feingranularem Pin-/Pad-Level für die MCAL-Treiberkonfiguration und Signalzuweisung im AUTOSAR-Entwicklungsprozess.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>Hardware Element</code> (<code>HwElement</code>):</strong>\n<ul class=\"fig-list\"><li>Basiskomponente des Metamodells zur Repräsentation physischer Einheiten (z. B. gesamte ECU, Mikrocontroller, Processing Unit/Core, Peripheriemodul, Flash/RAM, Transceiver, Sensoren/Aktoren).\n</li><li><strong>Hierarchische Schachtelung:</strong> Rekursive Aggregation (<code>HwElement</code> enthält Sub-<code>HwElement</code>e). Ermöglicht hierarchische Sichten (ECU → Microcontroller → Peripherie-IPs).\n</li></ul>\n</li><li><strong><code>Hardware Pin Group</code> (<code>HwPinGroup</code>):</strong>\n<ul class=\"fig-list\"><li>Logische oder funktionale Bündelung mehrerer Pins eines Hardware-Elements (z. B. SPI-Interface mit MOSI/MISO/CLK/CS, CAN-Tx/Rx, Port-Bank).\n</li><li>Dient als Zwischenabstraktion, um Verbindungen modular und übersichtlich ohne voll aufgelöste Einzeldraht-Modellierung zu definieren.\n</li></ul>\n</li><li><strong><code>Hardware Pin</code> (<code>HwPin</code>):</strong>\n<ul class=\"fig-list\"><li>Kleinste diskrete Modellierungseinheit; repräsentiert ein physisches/elektrisches Pad, Ball (BGA) oder Lead (Gehäuseanschluss) eines Halbleiters bzw. Steckverbinders.\n</li></ul>\n</li><li><strong><code>Hardware Connection</code> (<code>HwConnection</code>):</strong>\n<ul class=\"fig-list\"><li>Assoziations- bzw. Verbindungsklasse zur Modellierung physikalischer/elektrischer Signalpfade (Leiterbahnen, Kabelbäume, Busse).\n</li><li><strong>Mehrstufige Modellierungsgranularität (Multi-Level Abstraction):</strong>\n<ol class=\"fig-list\"><li><em>Element-to-Element:</em> Verbindung direkt zwischen zwei <code>HwElement</code>-Instanzen (abstrakter Strukturüberblick ohne Pin-Detail).\n</li><li><em>Group-to-Group / Group-to-Pin:</em> Verbindung zwischen <code>HwPinGroup</code> und Ziel-Pins (z. B. Interface-Level).\n</li><li><em>Pin-to-Pin:</em> Diskrete Verdrahtung zur exakten Festlegung von Signalführung und elektrischen Parametern.\n</li></ol>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht anwendbar (statisches Deklarationsmodell):</strong> Das Diagramm definiert rein statische Metadaten-Strukturen für ARXML-Beschreibungsdateien. Es existiert kein Laufzeitverhalten, keine State Machine und keine dynamische Interaktion (keine RTE-, Det- oder Dem-Beteiligung zur Laufzeit).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Generierung &amp; Tool-Kette:</strong>\n<ul class=\"fig-list\"><li>Fundament für Halbleiterhersteller (Semiconductor Vendors) zur Bereitstellung standardisierter Hardware-Beschreibungen (HwDescription ARXML).\n</li><li>Ermöglicht AUTOSAR-Autorensystemen (System Authoring Tools) Plausibilitätsprüfungen, ob zugeordnete Software-Komponenten (SWCs) und BSW-Module physikalisch auf den verfügbaren Kernen und Peripherien abgebildet werden können.\n</li></ul>\n</li><li><strong>MCAL-Konfiguration &amp; Signal-Pin-Mapping:</strong>\n<ul class=\"fig-list\"><li><strong>Port / DIO Driver:</strong> Das <code>HwPin</code>- und <code>HwPinGroup</code>-Modell steuert direkt die Generierung der MCAL-Port-Konfiguration (<code>PortPin</code>, Multiplexing-Optionen, Direction, Pull-Up/Pull-Down).\n</li><li><strong>Kommunikationstreiber (CAN/LIN/SPI/ETH):</strong> Die Abbildung von <code>HwPinGroup</code> auf Peripherie-Pins legt die Zuweisung von Hardware-Controllern zu physikalischen Transceivern auf dem PCB fest.\n</li></ul>\n</li><li><strong>Integrations-Constraint:</strong>\n<ul class=\"fig-list\"><li>Fehlende oder unzureichend aufgelöste Pin-Level-Modelle (<code>HwPin Connection</code>) verhindern die automatisierte Parametrisierung der I/O-Hardware-Abstraktionsschicht (IoHwAb) und der BSW-Treiberstacks, da Generator-Skripte zwingend die exakte Pin-ID für Register-Bitmasken benötigen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-6db55e35107c98cf", "to": "FIG-1b73dbcefe8c9461", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1b73dbcefe8c9461", "to": "FIG-5415339cbf79f867", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
